        {"새찬송가":"461", "통일찬송가":"397", "제목":"주 예수 내 마음에 들어와", "선정이유":"말씀에 귀를 열고 예수를 영접하는 결단의 찬송"},
        {"새찬송가":"338", "통일찬송가":"364", "제목":"내 주를 가까이 하게 함은", "선정이유":"하나님께 더 가까이 나아가는 결단의 찬송"}
