    표8_상담적용: [
        {"상황":"반복된 경고에도 변화 없이 살아가는 분", "성경원리":"하나님의 경고는 경험 많은 장로들조차 들어야 했다. 신앙 경력이 많아도 말씀에 귀를 기울여야 한다", "실제적용":"오랜 신앙 경험이 하나님의 경고를 무시하는 이유가 되어서는 안 된다"},
        {"상황":"공동체의 위기를 개인의 문제로만 보는 분", "성경원리":"'땅의 모든 거민'에게 선포한다. 재앙은 공동체 전체의 각성을 촉구한다", "실제적용":"개인의 신앙 문제도 중요하지만 공동체 전체의 영적 상태를 함께 살피라"},
        {"상황":"과거의 신앙 유산만 의지하며 나태한 분", "성경원리":"'너희 열조의 날'을 소환하는 것은 과거 자랑이 아니라 현재 비교를 위함이다", "실제적용":"조상의 신앙 유산을 자랑하지 말고 현재 자신의 신앙 상태를 점검하라"}
    ],
