        {"구절":"고전 10:11", "연결점":"이런 일이 일어난 것은 우리를 깨우치는 거울이 됨", "구분":"신약"},
        {"구절":"히 3:7-8", "연결점":"오늘 성령이 말씀하시거든 너희 마음을 강퍅하게 하지 말라", "구분":"신약"}
