        {"구절":"호 4:11", "연결점":"음행과 묵은 포도주와 새 포도주가 마음을 빼앗음", "구분":"구약"},
        {"구절":"암 6:6", "연결점":"포도주를 대접으로 마시며 요셉의 환난을 근심하지 않음", "구분":"구약"},
        {"구절":"사 24:11", "연결점":"거리에서 포도주를 찾아 부르짖으며 모든 기쁨이 사라짐", "구분":"구약"},
        {"구절":"롬 13:11-13", "연결점":"잠에서 깨어나야 할 때 방탕과 술 취하지 말라", "구분":"신약"},
        {"구절":"엡 5:14", "연결점":"잠자는 자여 깨어나라 죽은 자들 가운데서 일어나라", "구분":"신약"},
        {"구절":"살전 5:6-7", "연결점":"자는 자와 취하는 자는 밤에 속한다 우리는 깨어 있자", "구분":"신약"},
        {"구절":"약 4:9", "연결점":"슬퍼하며 애통하며 울찌어다 너희 웃음을 애통으로 바꾸라", "구분":"신약"}
