        {"새찬송가":"383", "통일찬송가":"391", "제목":"주 예수님 내 맘에 모셔", "선정이유":"삶의 주인으로 예수님을 모시는 헌신의 찬송"},
        {"새찬송가":"350", "통일찬송가":"380", "제목":"나의 주 하나님", "선정이유":"하나님의 주권과 능력을 찬양하는 찬송"}
