        {"구절":"합 1:6", "연결점":"강포한 갈대아 족속을 보내시는 하나님", "구분":"구약"},
        {"구절":"시 24:1", "연결점":"땅과 거기 충만한 것이 여호와의 것이라", "구분":"구약"},
        {"구절":"욥 4:10-11", "연결점":"사자의 포효와 하나님의 심판", "구분":"구약"},
        {"구절":"벧전 5:8", "연결점":"사자같이 삼킬 자를 찾는 마귀를 대적하라", "구분":"신약"},
        {"구절":"딤후 4:17", "연결점":"주께서 내 곁에 서서 사자의 입에서 건지심", "구분":"신약"},
        {"구절":"골 2:15", "연결점":"통치자와 권세들을 무력화하신 그리스도", "구분":"신약"},
        {"구절":"계 11:15", "연결점":"세상 나라가 우리 주의 나라가 되리로다", "구분":"신약"}
