        {"구절":"계 6:12-13", "연결점":"여섯째 인 - 해가 검어지고 달이 피 같이 되는 심판", "구분":"신약"},
        {"구절":"요 1:5", "연결점":"빛이 어둠에 비치되 어둠이 깨닫지 못하더라", "구분":"신약"}
