        {"새찬송가":"377", "통일찬송가":"502", "제목":"내 주는 강한 성이요", "선정이유":"강한 심판 앞에서 더 강하신 하나님을 신뢰하는 찬송"},
        {"새찬송가":"595", "통일찬송가":"605", "제목":"믿는 사람들은 주 군병", "선정이유":"하나님의 군대로 사는 신앙의 찬송"}
