    {"대지":"서론", "내용":"제사장들이 단과 낭실 사이에서 눈물로 기도한다. 이것이 목회자의 자리이다. 하나님과 성도 사이에서 눈물로 서는 것", "예화_적용":"성도를 위해 눈물로 기도한 목회자의 이야기"},
    {"대지":"1대지: 중보의 자리 (위치)", "내용":"낭실과 단 사이는 중보자의 자리. 목회자는 하나님과 성도 사이에서 기도하는 중보자", "예화_적용":"모세가 백성을 위해 하나님 앞에 간청한 출 32:32"},
    {"대지":"2대지: 눈물의 기도 (진실)", "내용":"울며 드리는 중보 기도는 형식이 아닌 진심. 성도를 위한 진정한 사랑이 눈물의 기도를 만든다", "예화_적용":"예레미야가 백성을 위해 눈물로 기도한 눈물의 선지자"},
    {"대지":"3대지: 하나님의 영광을 위한 기도 (목적)", "내용":"이방인이 하나님을 조롱하지 못하도록 구원을 구함. 기도의 목적이 자신의 편안함이 아닌 하나님의 영광임", "예화_적용":"하나님의 이름이 거룩히 여김을 받는 것이 기도의 목표 (마 6:9)"},
    {"대지":"결론", "내용":"눈물로 중보하는 기도자 없이는 공동체가 살아남기 어렵다. 누군가는 단과 낭실 사이에 서야 한다", "예화_적용":"중보 기도팀의 사역으로 교회가 변화된 간증"}
