    {"구절":"요일 2:1", "연결점":"예수 그리스도는 의로우신 자요 우리의 대언자", "구분":"신약"},
    {"구절":"엡 1:18", "연결점":"교회는 그리스도의 기업, 하나님의 소유", "구분":"신약"}
