    {"구절":"겔 36:5-6", "연결점":"열방을 향한 하나님의 열심과 이스라엘을 향한 긍휼", "구분":"구약"},
    {"구절":"슥 1:14", "연결점":"나 여호와가 예루살렘과 시온을 위하여 크게 질투하노라", "구분":"구약"},
    {"구절":"호 11:8", "연결점":"에브라임이여 내가 어찌 너를 놓겠느냐 - 하나님의 강렬한 사랑", "구분":"구약"},
    {"구절":"요 11:35", "연결점":"예수께서 눈물을 흘리심 - 인간 고통에 함께 하시는 하나님", "구분":"신약"},
    {"구절":"히 4:15", "연결점":"우리 연약함을 함께 체휼하신 대제사장", "구분":"신약"},
    {"구절":"엡 5:25-27", "연결점":"그리스도는 교회를 사랑하시어 자신을 주심", "구분":"신약"},
    {"구절":"눅 15:20", "연결점":"아버지가 달려가 아들을 맞이함 - 뜨거운 하나님의 사랑", "구분":"신약"}
