    {"상황":"악한 자의 핍박을 당하는 성도", "성경원리":"하나님은 자기 백성을 위해 싸우시는 군사적 하나님이시다 (출 14:14)", "실제적용":"하나님이 대신 싸워주신다는 믿음을 갖고 복수와 보복을 하나님께 맡기기"},
    {"상황":"큰 은혜를 경험했음에도 감사하지 못하는 성도", "성경원리":"하나님이 큰 일을 행하셨을 때 그것을 선포해야 한다 (욜 2:20, 시 126:2-3)", "실제적용":"받은 은혜 목록을 작성하고 감사 기도를 드리는 시간 갖기"}
