    {"대지":"서론", "내용":"땅에게도 두려워 말라고 하신다. 자연에게도 기뻐하라고 명하신다. 하나님의 회복은 온 세상을 기쁨으로 채운다", "예화_적용":"봄이 와서 겨울의 황폐함이 사라지는 자연의 기쁨"},
    {"대지":"1대지: 두려움을 이기는 믿음 (용기)", "내용":"두려워하지 말라는 명령은 하나님의 능력에 근거함. 하나님이 함께하실 때 두려움은 사라진다", "예화_적용":"사자굴의 다니엘, 풀무불의 세 청년 - 두려워하지 않은 믿음"},
    {"대지":"2대지: 기쁨으로 응답하라 (감사)", "내용":"하나님의 큰 일에 기뻐함은 의무이자 권리. 구원받은 성도는 기뻐할 이유가 있다", "예화_적용":"필립보서 4:4 - 주 안에서 항상 기뻐하라는 명령"},
    {"대지":"3대지: 온 피조물의 회복 (생태)", "내용":"땅이 기뻐할 것은 자연의 회복도 포함됨. 하나님의 구원은 인간만이 아닌 전 피조물을 회복시킴", "예화_적용":"로마서 8:19-22 - 피조물의 탄식과 회복의 소망"},
    {"대지":"결론", "내용":"두려움은 하나님 앞에 사라진다. 기뻐하라 - 이것이 하나님의 명령이다. 하나님이 큰 일을 행하셨기 때문이다", "예화_적용":"기쁨을 잃었다가 회복한 성도의 간증"}
