    {"대지":"결론", "내용":"하나님의 복은 가득하고 넘친다. 우리의 삶이 다시 가득 찰 것을 믿자. 기도하고 구하면 하나님이 채우신다", "예화_적용":"물질적·영적으로 풍성해진 삶의 간증"}
