    {"구분":"만민에게 임하는 성령", "내용":"계층, 성별, 나이를 초월한 성령 역사의 예표", "그리스도연결":"그리스도 안에서 유대인이나 헬라인, 종이나 자유인, 남자나 여자가 하나 (갈 3:28)"},
    {"구분":"예언과 이상의 새 시대", "내용":"하나님의 계시가 보편화되는 새 시대", "그리스도연결":"성령이 진리 가운데로 인도하심 (요 16:13), 말씀이 모든 성도에게 열림"}
