    {"대지":"결론", "내용":"이미 성령이 부어졌다. 오순절에 이 약속이 성취되었고 지금도 성령이 우리 안에 계신다. 성령 충만을 구하라", "예화_적용":"성령의 역사로 변화된 삶의 간증"}
