    {"새찬송가":"623", "통일찬송가":"620", "제목":"빠른 재림 속히 임하소서", "선정이유":"재림의 날을 소망하며 기다리는 찬송"},
    {"새찬송가":"174", "통일찬송가":"173", "제목":"주의 날이 오리니", "선정이유":"여호와의 크고 두려운 날을 선포하는 찬송"}
