    {"항목":"하나님의 땅 나눔", "내용":"열방이 하나님의 소유인 이스라엘의 땅을 자기들끼리 나눔. 이것은 하나님의 소유권에 대한 도전이므로 심판을 받음", "목회적활용":"창조주 하나님의 소유권을 무시하는 것이 심판의 원인임을 가르침"}
