    {"대지":"2대지: 자기 백성을 핍박한 죄 (박해)", "내용":"이스라엘을 흩고 핍박한 것이 심판의 이유. 하나님의 백성을 건드리는 것은 하나님을 건드리는 것", "예화_적용":"초대 교회 박해자 사울이 다메섹에서 '왜 나를 박해하느냐'는 음성을 들은 사건"},
    {"대지":"3대지: 하나님의 소유권 (창조 신학)", "내용":"하나님의 땅을 제멋대로 나눈 것이 심판의 원인. 창조주 하나님의 소유권에 대한 도전", "예화_적용":"레 25:23 - 땅은 내 것이라"},
    {"대지":"결론", "내용":"하나님의 심판은 반드시 온다. 공의로우신 하나님 앞에 서게 될 날을 준비하라. 하나님의 백성을 사랑하고 존중하는 것이 심판을 피하는 길이다", "예화_적용":"마 25:45 - 형제 중 작은 자에게 한 것이 곧 내게 한 것"}
