    {"상황":"하나님의 심판을 두려워하는 성도", "성경원리":"의인에게 심판의 날은 구원의 날이다 (욜 2:32, 계 20:15)", "실제적용":"구원의 확신을 굳히고 심판을 두려움이 아닌 소망으로 바라보도록 인도"},
    {"상황":"세상의 불의 앞에 무력감을 느끼는 성도", "성경원리":"하나님이 사방의 모든 열방을 심판하신다 - 아무도 예외없음 (욜 3:12)", "실제적용":"하나님의 보편적 심판을 신뢰하며 세상의 불의에 끌려가지 않고 의롭게 살도록 격려"}
