    {"상황":"다른 사람에게 폭력이나 강포를 행한 사람", "성경원리":"무고한 자에게 강포를 행한 나라는 황폐하게 된다 (욜 3:19)", "실제적용":"죄의 심각성을 인식하고 진심으로 회개하며 피해자와의 화해를 위해 구체적으로 행동하도록 인도"}
